function routeHash(){if(location.hash)return location.hash;const path=location.pathname.replace(/^\/|\/$/g,'');return '#'+(path==='administrator'?'admin':path||'home')}
function routePath(route){return route==='home'?'/':route==='admin'?'/administrator/':'/'+route+'/'}
function navigate(route){history.pushState(null,'',routePath(route));window.dispatchEvent(new Event('hashchange'))}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!u.hash)return;e.preventDefault();navigate(u.hash.slice(1)||'home')});
window.addEventListener('popstate',()=>{window.scrollTo(0,0);render()});
