const safeImage=s=>/^(assets\/|data:image\/(png|jpeg|webp);base64,|https:\/\/)/.test(s)?esc(s):'assets/ritsa.jpg';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function chips(selected='Все'){return `<div class="chips">${categories.map(c=>`<button class="chip ${c===selected?'active':''}" data-category="${c}">${c==='Природа'?'✧ ':''}${c}</button>`).join('')}</div>`}
function cityOptions(value='',all=true){return `${all?'<option value="">Все города выезда</option>':''}${['Сухум','Новый Афон','Гагра','Пицунда','Гудаута'].map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('')}`}
function priceFor(t){return filters.city&&t.cities[filters.city]?t.cities[filters.city].adult:Math.min(...Object.values(t.cities).map(x=>x.adult))}
function card(t){return `<article class="card"><div class="card-image"><a class="card-photo-stack" href="#tour/${esc(t.id)}">${[...new Set([t.image,...(t.gallery||[])])].filter(Boolean).map((src,i)=>`<img class="card-photo ${i===0?'active':''}" src="${safeImage(src)}" alt="${i===0?esc(t.title):''}" loading="lazy">`).join('')}</a><span class="pill">${t.popular?'Выбор путешественников':esc(t.categories[0]||'Экскурсия')}</span><button class="favorite ${favorites.includes(t.id)?'saved':''}" data-favorite="${esc(t.id)}" aria-label="${favorites.includes(t.id)?'Убрать из избранного':'Добавить в избранное'}">${favorites.includes(t.id)?'♥':'♡'}</button></div><div class="card-body"><p class="card-meta">${esc(t.duration)} · ${esc(t.format)} · ${esc(t.region)} район</p><a href="#tour/${esc(t.id)}"><h3>${esc(t.title)}</h3></a><p class="card-description">${esc(t.description)}</p><div class="card-bottom"><span class="price"><small>от </small>${money(priceFor(t))}<small> / человек</small></span><a class="circle" href="#tour/${esc(t.id)}" aria-label="Открыть ${esc(t.title)}" style="display:grid;place-items:center">↗</a></div></div></article>`}
function mapBlock(){return `<section class="section map-section" id="map"><div class="map-canvas">${window.ABKHAZIA_MAP.replace(/<text[\s\S]*?<\/text>/g,'')}</div><div class="map-info" id="district-tours" aria-live="polite">${districtCards(activeDistrict)}</div></section>`}
const faqs=`<section class="faq" id="faq"><h2>Перед путешествием</h2><details><summary>Откуда начинается экскурсия?</summary><p>Выберите город выезда в каталоге. В форме заявки появится памятка о посадке. Точное место и время сбора подтверждает менеджер.</p></details><details><summary>Как проверить мой трансфер?</summary><p>Откройте действующий сервис отслеживания. <a class="link-arrow" href="https://track.apsuatur.ru:8181/" target="_blank" rel="noopener">Проверить трансфер ↗</a></p></details><details><summary>Можно ли добавить сайт на экран телефона?</summary><p>На iPhone откройте сайт в Safari и выберите «Поделиться» → «На экран Домой». На Android используйте пункт «Установить приложение» или «Добавить на главный экран» в меню браузера. Доступность установки зависит от браузера и режима доступа к сайту.</p></details><details><summary>Можно ли забронировать поездку в этом прототипе?</summary><p>Пока можно пройти все шаги и сохранить демонстрационный черновик. Реальные заявки, вход и история поездок будут подключены к серверу на следующем этапе.</p></details></section>`;
function journal(){return `<section class="section" id="journal"><div class="section-heading"><div><h2><a href="#journal">Дневник путешествий</a></h2><p class="journal-subtitle">Истории, фотографии и советы наших гостей</p></div><a class="secondary" href="#journal">Все истории</a></div><div class="story-grid">${publishedStories().length?publishedStories().slice(0,3).map(storyCard).join(''):'<div class="journal-empty"><h3>Как прошла ваша поездка?</h3><p>Поделитесь впечатлениями, любимыми местами и советами для будущих путешественников.</p><button class="primary" data-action="new-story">Оставить историю о своей поездке</button></div>'}</div></section>`}
function rankedTours(){const serverCounts=read('bookingCounts',{});return tours.filter(t=>t.visible!==false).sort((a,b)=>{const count=t=>Number(serverCounts[t.id]||0)+orders.filter(o=>o.tourId===t.id&&o.type==='excursion').length;return count(b)-count(a)||Number(b.popular)-Number(a.popular)})}
function popularCarousel(){const list=popularSelection();return `<section class="section popular-section"><div class="section-heading"><div><p class="eyebrow">Вдохновение для вашего отпуска</p><h2>Популярные маршруты</h2></div><div class="carousel-arrows"><button class="glass" data-carousel-step="-1" aria-label="Предыдущий маршрут">←</button><button class="glass" data-carousel-step="1" aria-label="Следующий маршрут">→</button></div></div><div class="popular-track" id="popular-track" tabindex="0" aria-label="Популярные маршруты. Листайте стрелками или свайпом">${list.map((t,i)=>`<article class="popular-slide"><img src="${safeImage(banners.popular[t.id]?.image||t.image)}" alt="${esc(t.title)}" loading="lazy" draggable="false"><div class="popular-overlay"></div><span class="slide-number">0${i+1} / 0${list.length}</span><div class="popular-copy"><span class="glass slide-tag">${esc(t.categories[0])} · ${esc(t.duration)}</span><h3>${esc(banners.popular[t.id]?.title||t.title)}</h3><p>${esc(banners.popular[t.id]?.description||t.description)}</p><div class="popular-bottom"><a class="glass" href="#tour/${esc(t.id)}">Открыть маршрут ↗</a><span>от ${money(priceFor(t))}<small>за человека</small></span></div></div></article>`).join('')}</div><div class="carousel-progress">${list.map((t,i)=>`<button data-carousel-index="${i}" class="${i===0?'active':''}" aria-label="Маршрут ${i+1}"><span></span></button>`).join('')}</div></section>`}
function reviewsBlock(){return `<section class="section reviews-section" id="reviews"><div class="reviews-intro"><p class="eyebrow">Путешествия глазами наших гостей</p><h2>Впечатления,<br>которыми делятся.</h2><p>Отзывы об «Апсуа Тур» на Яндекс Картах — от тех, кто уже путешествовал с нами.</p><a class="glass reviews-link" href="https://yandex.ru/maps/org/apsua_tur/132935970380/reviews" target="_blank" rel="noopener">Все отзывы на Яндекс Картах ↗</a><p class="reviews-fallback">Если отзывы не загрузились, откройте карточку по ссылке.</p></div><div class="reviews-widget"><iframe src="https://yandex.ru/maps-reviews-widget/132935970380?comments" title="Отзывы об Апсуа Тур на Яндекс Картах" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="reviews-source" href="https://yandex.ru/maps/org/apsua_tur/132935970380/reviews" target="_blank" rel="noopener">Апсуа Тур · отзывы на Яндекс Картах ↗</a></div></section>`}
function home(){return `<div class="wrap reveal"><section class="hero"><div><p class="eyebrow">Море, горы и настоящее гостеприимство</p><h1>${esc(banners.heroTitle)}<br><em>${esc(banners.heroSubtitle)}</em></h1><p>${esc(banners.heroDescription)}</p><div class="hero-buttons"><a class="primary" href="#catalog">Выбрать путешествие <span>↗</span></a><a class="glass" href="#transfer">Заказать трансфер</a></div><div class="hero-meta"><div><span>От моря до гор</span>Маршруты по всей Абхазии</div><div><span>С 2011 года</span>Организуем трансферы</div></div></div><div class="hero-photo"><img src="${safeImage(banners.heroImage)}" alt="Путешествие по Абхазии" draggable="false"></div><div class="hero-stamp"><span>✧</span>ближе<br>к природе</div></section><form class="search-panel" id="home-search"><label>Откуда выезжаем<select name="city">${cityOptions(filters.city)}</select></label><label>Что хочется увидеть<input name="query" placeholder="Озеро, водопады, древние храмы…" value="${esc(filters.query)}"></label><button class="primary">Найти маршрут ↗</button></form>${popularCarousel()}<section class="section"><div class="section-heading"><div><p class="eyebrow">Что вам ближе?</p><h2>Найдите своё путешествие</h2></div><a class="link-arrow" href="#catalog">Весь каталог ↗</a></div>${chips()}<div class="cards">${rankedTours().slice(0,3).map(card).join('')}</div></section><section class="wide-banner"><div class="transfer-art"><img class="transfer-banner-photo" src="${safeImage(banners.transferImage||'assets/transfer-panorama.webp')}" alt="Минивэн у моря и гор — иллюстрация трансфера" loading="lazy" decoding="async"></div><div class="transfer-cta"><a href="#transfer" class="primary">Выбрать трансфер</a></div></section>${mapBlock()}${journal()}${reviewsBlock()}${faqs}</div>`}
function matching(){let a=tours.filter(t=>t.visible!==false&&(!filters.city||t.cities[filters.city])&&(!filters.query||(t.title+' '+t.description+' '+t.categories.join(' ')).toLowerCase().includes(filters.query.toLowerCase()))&&(filters.category==='Все'||t.categories.includes(filters.category))&&(!filters.region||t.region===filters.region)&&(!filters.format||t.format===filters.format)&&(!filters.transport||t.transport===filters.transport)&&priceFor(t)<=filters.max);if(filters.sort==='price')a.sort((x,y)=>priceFor(x)-priceFor(y));else if(filters.sort==='name')a.sort((x,y)=>x.title.localeCompare(y.title,'ru'));else a.sort((x,y)=>Number(y.popular)-Number(x.popular));return a}
function catalog(){return `<div class="wrap reveal"><div class="page-head"><p class="eyebrow">Путешествуйте в своём ритме</p><h1>Экскурсии по Абхазии</h1><p>Выберите город выезда и то, что любите. Остальное — дело маршрута.</p></div><div class="filters"><select id="filter-city" aria-label="Город выезда">${cityOptions(filters.city)}</select><input id="filter-query" aria-label="Поиск экскурсий" placeholder="Найти озеро, храм или водопад" value="${esc(filters.query)}"><select id="filter-sort" aria-label="Сортировка"><option value="recommended">Рекомендуем</option><option value="price" ${filters.sort==='price'?'selected':''}>Сначала дешевле</option><option value="name" ${filters.sort==='name'?'selected':''}>По названию</option></select><button class="secondary" data-action="reset">Сбросить фильтры</button></div>${chips(filters.category)}<div class="filter-more"><label>Формат <select id="filter-format"><option value="">Любой</option><option ${filters.format==='Групповая'?'selected':''}>Групповая</option><option ${filters.format==='Индивидуальная'?'selected':''}>Индивидуальная</option></select></label><label>Транспорт <select id="filter-transport"><option value="">Любой</option><option ${filters.transport==='Микроавтобус'?'selected':''}>Микроавтобус</option><option>Пешком</option><option>Джип</option><option>Катер</option></select></label><label>До <input type="range" id="filter-max" min="1000" max="10000" step="500" value="${filters.max}"> <span id="max-value">${money(filters.max)}</span></label>${filters.region?`<button class="chip" data-action="clear-region">${esc(filters.region)} район ×</button>`:''}</div><p class="results-label" id="results-label"></p><div class="cards" id="catalog-cards"></div>${mapBlock()}</div>`}
function updateResults(){const a=matching();$('#results-label').textContent=`Найдено маршрутов: ${a.length} · цены для взрослых, без дополнительных услуг`;$('#catalog-cards').innerHTML=a.length?a.map(card).join(''):'<div class="empty"><h3>Здесь пока нет маршрутов</h3><p>Попробуйте другой город или снимите часть фильтров.</p><button class="primary" data-action="reset">Сбросить фильтры</button></div>'}
function dateISO(d){const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function calendarHTML(){let month=new Date(booking.month),now=new Date(),end=new Date();end.setMonth(end.getMonth()+1);let first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7,last=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const minKey=now.getFullYear()*12+now.getMonth(),maxKey=end.getFullYear()*12+end.getMonth(),key=month.getFullYear()*12+month.getMonth();return `<div class="calendar-shell"><div class="calendar-topline"><span>Выберите дату</span><small>На месяц вперёд</small></div><div class="calendar-head"><button class="calendar-arrow" type="button" data-cal="-1" ${key<=minKey?'disabled':''} aria-label="Предыдущий месяц">‹</button><span>${month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</span><button class="calendar-arrow" type="button" data-cal="1" ${key>=maxKey?'disabled':''} aria-label="Следующий месяц">›</button></div><div class="calendar" role="group" aria-label="Выбор даты экскурсии">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span class="weekday">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:last},(_,i)=>{let d=dateISO(new Date(month.getFullYear(),month.getMonth(),i+1)),disabled=d<dateISO(now)||d>dateISO(end),weekend=new Date(d+'T12:00:00').getDay()%6===0;return `<button type="button" data-date="${d}" aria-label="${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}" aria-pressed="${d===booking.date}" class="${d===booking.date?'active':''} ${weekend?'weekend':''} ${d===dateISO(now)?'today':''}" ${disabled?'disabled':''}><span>${i+1}</span>${!disabled?'<i></i>':''}</button>`}).join('')}</div><div class="selected-date"><span>✓</span><div><small>Ваш день путешествия</small><p>${new Date(booking.date+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</p></div></div></div><p class="map-note calendar-note">Демо: доступность дат подтвердит сервер после подключения.</p>`}
function pickup(city){if(city==='Сухум')return 'Забираем по адресу проживания в черте города Сухум, за исключением тупиков, проездов и участков с плохой дорогой. В таких случаях назначаем ближайшую к адресу проживания точку сбора.';if(city==='Новый Афон')return 'Забираем по адресу проживания в черте города Новый Афон, а также по центральной трассе от Сухума к Новому Афону, за исключением тупиков, проездов и участков с плохой дорогой. В таких случаях назначаем ближайшую к адресу проживания точку сбора.';return 'Место посадки и время встречи подтверждает менеджер.'}
function timesFor(t,city,date){const month=new Date(date+'T12:00:00').getMonth();let summer=month>=4&&month<=9;if(!(summer?t.summer:t.winter))return [];let ts=(summer?t.summerTimes:t.winterTimes).split(',').map(x=>x.trim()).filter(Boolean);if(city==='Новый Афон'&&['ritsa','ring','premium'].includes(t.id))ts=ts.map(x=>`${String(Number(x.split(':')[0])+1).padStart(2,'0')}:${x.split(':')[1]}`);return ts}
function detail(t){if(!booking||booking.id!==t.id){booking={id:t.id,city:filters.city&&t.cities[filters.city]?filters.city:Object.keys(t.cities)[0],date:dateISO(new Date()),month:dateISO(new Date()),adults:1,children:0}}return `<div class="wrap reveal"><div class="page-head"><a href="#catalog" class="link-arrow">← Все экскурсии</a><h1>${esc(t.title)}</h1><p>${esc(t.duration)} · ${esc(t.format)} · ${esc(t.transport)}</p></div><div class="detail-hero"><img src="${safeImage(t.image)}" alt="${esc(t.title)}"></div>${t.gallery?.length?`<div class="gallery">${t.gallery.map(img=>`<img src="${safeImage(img)}" alt="Фото маршрута">`).join('')}</div>`:''}<div class="detail-layout"><div class="detail-copy"><p class="eyebrow">${esc(t.region)} район</p><h2>Впечатления, ради которых стоит поехать</h2><p>${esc(t.description)}</p><h2>Ваше путешествие</h2><div class="note">${esc(t.categories.join(' · '))}<br>${esc(t.duration)} в дороге и на остановках. Подробную программу и условия участия подтвердит менеджер.</div><h2>Полезно знать</h2><p>Выберите город выезда — от него зависят цена и время. Укажите адрес проживания и контакт для связи. Точное место посадки, дополнительные расходы и расписание уточняются до поездки.</p><h2>Цена для вашего города</h2>${Object.entries(t.cities).map(([city,p])=>`<div class="order-card"><span>${esc(city)}</span><span>Взрослый ${money(p.adult)}<br><small>Ребёнок ${money(p.child)}</small></span></div>`).join('')}</div><aside class="booking-card"><h3>Соберём ваш день</h3>${demo}<form id="booking-form"><label class="field">Город выезда<select name="city" id="booking-city">${Object.keys(t.cities).map(c=>`<option ${c===booking.city?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="note" id="pickup-note">${pickup(booking.city)}</div><div id="calendar-wrap">${calendarHTML()}</div><label class="field">Время выезда<select name="time" id="booking-time" required></select></label><div class="form-grid" style="margin:15px 0"><label class="field">Взрослые<input name="adults" type="number" min="1" max="30" value="1" required></label><label class="field">Дети<input name="children" type="number" min="0" max="30" value="0" required></label></div><label class="field">Ваше имя<input name="name" autocomplete="name" required placeholder="Как к вам обращаться"></label><label class="field" style="margin-top:12px">Телефон<input name="phone" type="tel" autocomplete="tel" required minlength="7" placeholder="+7 …"></label><label class="field" style="margin-top:12px">Адрес проживания<input name="address" required placeholder="Гостиница, улица, дом"></label><label class="field" style="margin-top:12px">Мессенджер на этом номере<select name="messenger"><option>Не указан</option><option>Telegram</option><option>WhatsApp</option><option>MAX</option></select></label><label class="contact-checkbox" style="margin:12px 0"><input type="checkbox" name="same-number">Подтверждаю: выбранный мессенджер привязан к указанному выше номеру</label><label class="field">Дополнительный контакт<input name="extra" placeholder="Другой номер или email — если есть"></label><div class="card-bottom" style="margin-top:20px"><span>Итого</span><span class="price" id="booking-total"></span></div><button class="primary">Сохранить демо-заявку ↗</button></form></aside></div>${faqs}</div>`}
function updateBooking(){const t=tours.find(t=>t.id===booking.id);$('#pickup-note').textContent=pickup(booking.city);const ts=timesFor(t,booking.city,booking.date);$('#booking-time').innerHTML=ts.length?ts.map(v=>`<option>${esc(v)}</option>`).join(''):'<option value="">Нет расписания для выбранного сезона</option>';$('#booking-form button.primary').disabled=!ts.length;const f=$('#booking-form');const total=t.cities[booking.city].adult*Number(f.adults.value)+t.cities[booking.city].child*Number(f.children.value);$('#booking-total').textContent=money(total)}
function transferPage(){const labels=['Выберите тип трансфера','Куда едем?','Когда встречаем / когда отправляемся?','Населённый пункт в Абхазии','Сколько едет человек?','Контакты и проверка'];let content='';switch(transfer.step){case 0:content=`<div class="option-list">${['Встреча','Обратный трансфер'].map(t=>`<button class="option ${transfer.type===t?'selected':''}" type="button" data-transfer-type="${t}">${t}<span>${t==='Встреча'?'Из аэропорта или вокзала — в Абхазию':'Из места проживания — в аэропорт или на вокзал'}</span></button>`).join('')}</div>`;break;case 1:content=`<div class="option-list">${transferServices.map(x=>`<button class="option ${transfer.place===x.id?'selected':''}" type="button" data-transfer-place="${esc(x.id)}">${esc(x.name)}<span>${esc(x.description)}</span></button>`).join('')}</div>`;break;case 2:content=`<div class="form-grid"><label class="field">Дата<input name="date" type="date" min="${dateISO(new Date())}" value="${esc(transfer.date||'')}" required></label><label class="field">Время ${transfer.type==='Встреча'?'прибытия':'выезда'}<input name="time" type="time" value="${esc(transfer.time||'')}" required></label><label class="field full">Номер рейса / поезда<input name="flight" placeholder="Например, SU 1234" value="${esc(transfer.flight||'')}"></label></div>`;break;case 3:content=`<label class="field">Населённый пункт<select name="city">${cityOptions(transfer.city,false)}</select></label><label class="field" style="margin-top:18px">Адрес в Абхазии<input name="address" value="${esc(transfer.address||'')}" required placeholder="Название отеля, улица, дом"></label><div class="note">${esc(transferServices.find(x=>x.id===transfer.place)?.name||'Трансфер')} · стоимость зависит от этого пункта отправления и вашего направления. ${transferServices.find(x=>x.id===transfer.place)?.prices[transfer.city]?money(transferServices.find(x=>x.id===transfer.place).prices[transfer.city])+' за человека.':'Тариф ещё не заполнен — стоимость требует подтверждения.'}</div>`;break;case 4:content=`<div class="form-grid"><label class="field">Взрослые<input name="people" type="number" min="1" max="50" value="${transfer.people}" required></label><label class="field">Дети<input name="children" type="number" min="0" max="50" value="${transfer.children||0}" required></label><label class="field full">Багаж и пожелания<textarea name="comment" placeholder="Детское кресло, крупный багаж…">${esc(transfer.comment||'')}</textarea></label></div>`;break;default:content=`<div class="note">${esc(transfer.type)} · ${esc(transferServices.find(x=>x.id===transfer.place)?.name)}<br>${esc(transfer.city)}, ${esc(transfer.address)}<br>${esc(transfer.date)} в ${esc(transfer.time)} · взрослых: ${esc(transfer.people)}, детей: ${esc(transfer.children||0)}</div><div class="form-grid"><label class="field">Ваше имя<input name="name" required autocomplete="name" value="${esc(transfer.name||'')}"></label><label class="field">Телефон<input name="phone" type="tel" minlength="7" required autocomplete="tel" value="${esc(transfer.phone||'')}"></label><label class="field full">Мессенджер на указанном номере<select name="messenger"><option>Не указан</option><option>Telegram</option><option>WhatsApp</option><option>MAX</option></select></label><label class="contact-checkbox full"><input name="same-number" type="checkbox">Подтверждаю, что мессенджер привязан к этому номеру</label><label class="field full">Дополнительный контакт<input name="extra" placeholder="Если есть"></label></div>`}
return `<div class="wrap reveal"><div class="page-head"><p class="eyebrow">Поездка начинается со спокойствия</p><h1>Ваш трансфер в Абхазии</h1><p>Аэропорты Сочи и Сухума, вокзал Адлера. Встреча и обратная поездка.</p></div><div class="transfer-form">${demo}<p class="eyebrow">Шаг ${transfer.step+1} из 6</p><div class="steps">${labels.map((x,i)=>`<span class="step ${i<=transfer.step?'active':''}"></span>`).join('')}</div><h2>${labels[transfer.step]}</h2><form id="transfer-form">${content}<div class="form-actions">${transfer.step?'<button type="button" class="secondary" data-action="transfer-back">← Назад</button>':'<span></span>'}<button class="primary">${transfer.step===5?'Сохранить демо-заявку':'Продолжить'} ↗</button></div></form></div><p style="text-align:center"><a class="link-arrow" target="_blank" rel="noopener" href="https://track.apsuatur.ru:8181/">Уже заказали? Проверить трансфер ↗</a></p></div>`}
function account(){const mine=orders.filter(o=>o.owner===user?.contact);return `<div class="wrap reveal"><div class="page-head"><p class="eyebrow">Всё о ваших путешествиях</p><h1>Личный кабинет</h1></div><div class="dashboard-grid"><aside class="sidebar"><h3>Добро пожаловать</h3><p>${esc(user.contact)}<br>Демонстрационный профиль</p><button class="secondary" data-action="logout">Выйти</button><p style="margin-top:20px">Настоящий вход и постоянная история на сервере будут подключены позже.</p></aside><div>${demo}<h2 style="font-size:30px;margin-bottom:25px">Мои заявки</h2>${mine.length?mine.map(o=>`<div class="order-card"><div><p>${esc(o.id)}</p><h3>${esc(o.title)}</h3><p>${esc(o.date)} · ${esc(o.city)} ${o.time?'· '+esc(o.time):''}</p>${o.total?`<p>${money(o.total)}</p>`:''}</div><span class="status">${esc(o.status)}</span></div>`).join(''):'<div class="empty"><h3>Впереди — новые впечатления</h3><p>Здесь появятся ваши демонстрационные заявки.</p><a href="#catalog" class="primary">Выбрать экскурсию ↗</a></div>'}<h2 style="font-size:30px;margin:35px 0 25px">Избранное</h2><div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${favorites.length?tours.filter(t=>favorites.includes(t.id)).map(card).join(''):'<p style="color:var(--muted)">Сохраняйте понравившиеся маршруты сердечком на карточке.</p>'}</div></div></div></div>`}
function showLogin(){const modal=$('#modal');$('#modal-body').innerHTML=`<p class="eyebrow">Ваши путешествия всегда рядом</p><h2>Личный кабинет</h2><p>В готовом сервисе вход будет по коду на телефон или почту.</p>${demo}<form id="login-form"><label class="field">Телефон или email<input name="contact" required placeholder="+7 … или name@example.ru"></label><button class="primary">Открыть демонстрационный профиль ↗</button><p style="font-size:11px;margin-top:15px">Код не отправляется. Это демонстрация интерфейса без проверки личности.</p></form>`;modal.showModal()}
function admin(){if(adminTab==='reviews')return reviewsAdmin();if(adminTab==='banners')return bannerAdmin();return `<div class="wrap reveal"><div class="page-head"><p class="eyebrow">Демонстрационный редактор</p><h1>Управление услугами</h1><p>Проверяем удобство редактирования. Изменения сохраняются только в вашем браузере. Защищённую панель и серверное сохранение подключим отдельно.</p></div><div class="admin-tabs"><button class="chip ${adminTab==='tours'?'active':''}" data-admin-tab="tours">Экскурсии</button><button class="chip ${adminTab==='transfers'?'active':''}" data-admin-tab="transfers">Трансферы</button><button class="chip" data-admin-tab="banners">Баннеры</button><button class="chip" data-admin-tab="reviews">Отзывы</button></div><div class="admin-toolbar"><button class="primary" data-action="${adminTab==='tours'?'new-tour':'new-transfer'}">+ Добавить ${adminTab==='tours'?'экскурсию':'трансфер'}</button><button class="secondary" data-action="restore">Восстановить демо-каталог</button></div><div class="admin-list">${adminTab==='tours'?tours.map((t,i)=>`<div class="admin-row" style="border-color:${t.categories.includes('Культура')?'#d3b47a':t.categories.includes('Религия')?'#aab1c7':'#9daf87'}"><img src="${safeImage(t.image)}" alt=""><div><h3>${esc(t.title)}</h3><small>${esc(t.categories.join(' · '))} · последняя правка: ${esc(t.updated)}<br>${Object.keys(t.cities).map(esc).join(', ')}</small></div><div class="row-actions"><button data-move="${esc(t.id)}" data-direction="-1" ${i===0?'disabled':''} aria-label="Переместить выше">↑</button><button data-move="${esc(t.id)}" data-direction="1" ${i===tours.length-1?'disabled':''} aria-label="Переместить ниже">↓</button><button data-edit="${esc(t.id)}">Изменить</button></div></div>`).join(''):transferServices.map(t=>`<div class="admin-row"><span style="font-size:30px">↗</span><div><h3>${esc(t.name)}</h3><small>${esc(t.description)}</small></div><div class="row-actions"><button data-edit-transfer="${esc(t.id)}">Изменить</button></div></div>`).join('')}</div></div>`}
function editTour(id){const t=tours.find(x=>x.id===id)||{id:'tour-'+Date.now(),title:'',description:'',image:'assets/lake2.jpg',gallery:[],categories:['Природа'],region:'Гудаутский',duration:'',format:'Групповая',transport:'Микроавтобус',cities:{'Сухум':{adult:0,child:0}},summer:true,winter:true,summerTimes:'09:00',winterTimes:'09:00',popular:false};window.editing=t.id;$('#app').innerHTML=`<div class="wrap reveal"><div class="page-head"><a href="#admin" class="link-arrow" data-action="back-admin">← Редактор каталога</a><h1>${t.title?'Редактировать экскурсию':'Новая экскурсия'}</h1></div><form id="admin-form" class="admin-form"><div class="form-grid"><label class="field full">Название<input name="title" required value="${esc(t.title)}"></label><label class="field full">Описание<textarea name="description" required>${esc(t.description)}</textarea></label><label class="field">Продолжительность<input name="duration" required value="${esc(t.duration)}" placeholder="Например, 8 часов"></label><label class="field">Район<select name="region">${['Гагрский','Гудаутский','Сухумский','Гулрыпшский','Очамчырский','Ткуарчальский','Галский'].map(r=>`<option ${r===t.region?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">Формат<select name="format">${['Групповая','Индивидуальная'].map(v=>`<option ${v===t.format?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Транспорт<select name="transport">${['Микроавтобус','Пешком','Джип','Катер'].map(v=>`<option ${v===t.transport?'selected':''}>${v}</option>`).join('')}</select></label></div><h3>Обложка и фотографии</h3><label class="field">Ссылка на обложку<input name="image" value="${esc(t.image)}"></label><label class="field" style="margin-top:12px">Загрузить обложку<input type="file" accept="image/jpeg,image/png,image/webp" id="cover-upload"></label><label class="field" style="margin-top:12px">Галерея · ссылки по одной на строке<textarea name="gallery">${esc((t.gallery||[]).join('\n'))}</textarea></label><label class="field">Добавить фотографии в галерею<input id="gallery-upload" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><h3>Города выезда и цены</h3>${['Сухум','Новый Афон','Гагра','Пицунда','Гудаута'].map((c,i)=>`<div class="city-price"><label><input type="checkbox" name="city-${i}" data-price-city="${i}" ${t.cities[c]?'checked':''}> ${c}</label><label class="field">Взрослый, ₽<input name="adult-${i}" type="number" min="0" value="${t.cities[c]?.adult||0}" ${t.cities[c]?'':'disabled'} required></label><label class="field">Ребёнок, ₽<input name="child-${i}" type="number" min="0" value="${t.cities[c]?.child||0}" ${t.cities[c]?'':'disabled'} required></label></div>`).join('')}<h3>Сезонное расписание</h3><div class="schedule-row">${['summer','winter'].map(s=>`<div><label><input type="checkbox" name="${s}" ${t[s]?'checked':''}> ${s==='summer'?'Летний период · май–октябрь':'Зимний период · ноябрь–апрель'}</label><label class="field" style="margin-top:10px">Время выезда из Сухума через запятую<input name="${s}Times" value="${esc(t[s+'Times'])}" placeholder="09:00,13:00"></label></div>`).join('')}</div><h3>Категории</h3><div class="chips">${categories.slice(1).map(c=>`<label class="chip"><input type="checkbox" name="category" value="${c}" ${t.categories.includes(c)?'checked':''}> ${c}</label>`).join('')}</div><label><input type="checkbox" name="popular" ${t.popular?'checked':''}> Показывать в популярных на главной</label><div class="form-actions"><button class="secondary" type="button" data-action="back-admin">Отмена</button><button class="primary">Сохранить изменения ↗</button></div></form></div>`;window.scrollTo(0,0)}
function editTransfer(id){const t=transferServices.find(x=>x.id===id)||{id:'transfer-'+Date.now(),name:'',description:'',prices:{}};window.editingTransfer=t.id;$('#app').innerHTML=`<div class="wrap"><div class="page-head"><h1>Редактор трансфера</h1></div><form id="transfer-admin" class="admin-form"><label class="field">Название точки отправления / прибытия<input name="name" value="${esc(t.name)}" required></label><label class="field" style="margin-top:15px">Описание<textarea name="description">${esc(t.description)}</textarea></label><h3>Тарифы по населённым пунктам</h3><p class="note">0 означает, что тариф ещё не заполнен. В форме заказа цена не будет заявлена.</p><div class="form-grid">${['Сухум','Новый Афон','Гагра','Пицунда','Гудаута'].map((c,i)=>`<label class="field">${c} · ₽ за человека<input name="price-${i}" type="number" min="0" required value="${t.prices[c]||0}"></label>`).join('')}</div><div class="form-actions"><button type="button" class="secondary" data-action="back-admin">Отмена</button><button class="primary">Сохранить</button></div></form></div>`;window.scrollTo(0,0)}
