async function imageFile(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Выберите JPEG, PNG или WebP');return ''}if(file.size>5000000){toast('Выберите изображение до 5 МБ');return ''}return new Promise(resolve=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,1200/im.width);c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL(file.type==='image/png'?'image/png':file.type==='image/webp'?'image/webp':'image/jpeg',.85))};im.onerror=()=>{toast('Не удалось прочитать изображение');resolve('')};im.src=r.result};r.readAsDataURL(file)})}
